// Estimation Ladder kit (Section 1)
function pickRung(btn) {
  document.querySelectorAll('.est-rung').forEach(r => r.classList.remove('picked'));
  btn.classList.add('picked');
}
function commitEstimate() {
  const sec = document.getElementById('estSection');
  const actual = parseFloat(sec.dataset.actual);
  const units = sec.dataset.units || '';
  const tol = parseFloat(sec.dataset.tolerance) || 0.2;
  const input = document.getElementById('estInput');
  const guess = parseFloat((input.value || '').replace(/[\s,]/g, ''));
  const fb = document.getElementById('estFeedback');
  const hdr = document.getElementById('estFbHeader');
  const body = document.getElementById('estFbBody');
  fb.classList.remove('close', 'far');
  if (isNaN(guess)) {
    fb.classList.add('far', 'visible');
    hdr.textContent = 'Type a number first.';
    body.textContent = 'Take a guess: even a rough one is fine. There are no wrong answers at this stage.';
    return;
  }
  const error = Math.abs(guess - actual) / actual;
  const shown = actual.toLocaleString('en-AU');
  fb.classList.add('visible');
  if (error <= tol) {
    fb.classList.add('close');
    hdr.textContent = `✓ Close: the model gives ${shown} ${units}`;
    body.textContent = `You guessed ${guess.toLocaleString('en-AU')}, off by about ${Math.round(error * 100)}%. The rate does the work: 70 beats/min × 60 min/h × 24 h/day = ${shown} beats per day.`;
  } else {
    fb.classList.add('far');
    const direction = guess > actual ? 'higher than' : 'lower than';
    hdr.textContent = `The model gives ${shown} ${units}`;
    body.textContent = `You guessed ${guess.toLocaleString('en-AU')}, which is ${direction} the model. Chain the rates: 70 beats per minute × 60 minutes per hour × 24 hours per day = ${shown} beats per day, about one hundred thousand.`;
  }
}

// Error Analysis kit (strategy section): numeric correction check
let errFound = false;
function pickErrLine(el) {
  if (errFound || el.classList.contains('dimmed')) return;
  if (el.dataset.isError === 'true') {
    el.classList.add('flagged-correct');
    errFound = true;
    document.querySelectorAll('.err-line').forEach(o => { if (o !== el) o.classList.add('dimmed'); });
    document.getElementById('errFeedback').classList.add('visible');
  } else {
    el.classList.add('flagged-wrong');
    setTimeout(() => el.classList.remove('flagged-wrong'), 600);
  }
}
function checkErrCorrection() {
  const input = document.getElementById('errCorrection');
  const expected = parseFloat(document.querySelector('.err-line[data-is-error="true"]').dataset.correctLine);
  const typed = parseFloat((input.value || '').replace(/\s+/g, ''));
  const msg = document.getElementById('errStatusMsg');
  input.classList.remove('correct', 'incorrect');
  if (!isNaN(typed) && Math.abs(typed - expected) < 1e-9) {
    input.classList.add('correct');
    msg.textContent = '✓ Correct. (25 − 10) ÷ 6 = 2.5 m/s²: the car gains 2.5 m/s every second.';
  } else if (!isNaN(typed) && Math.abs(typed - 9) < 1e-9) {
    input.classList.add('incorrect');
    msg.textContent = '✗ That is the student\'s answer. Convert both speeds to m/s first (divide by 3.6).';
  } else {
    input.classList.add('incorrect');
    msg.textContent = '✗ Not quite. Convert 36 km/h and 90 km/h to m/s, subtract, then divide by 6.';
  }
}

// Topic-specific instructions for the frame's fixed section text
(function () {
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  set('#tier1-body .sec-desc', 'Type just the number in each box: no units needed. Write the rate as a division first, then multiply or divide to use it.');
  set('#tier2-body .sec-desc', 'Convert units before you use a rate (km/h ÷ 3.6 = m/s; 1000 L = 1 kL; 60 min = 1 h). Type just the number.');
  set('#tier3-body .sec-desc', 'Cultural burning and rate of spread: use the chart and the model rules in Question 1 for every question. Type just the number.');
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> find the rate once (amount ÷ time), then every question is one multiplication (forwards) or one division (backwards). Check the units match before you calculate, and ask whether the answer is believable.';
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.textContent = 'Click a situation, then click the rate it produces. There are five matching pairs.';
})();
